nextflow_process {

    name "Test Process PRESEQ_LCEXTRAP"
    script "../main.nf"
    process "PRESEQ_LCEXTRAP"
    tag "modules"
    tag "modules_nfcore"
    tag "preseq"
    tag "preseq/lcextrap"

    test("sarscov2 - single_end") {
        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:true ],
                    [ file(params.modules_testdata_base_path + 'delete_me/preseq/SRR1003759_5M_subset.mr', checkIfExists: true) ]
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys:["log"])).match() }
            )
        }
    }

    test("sarscov2 - single_end - stub") {
        options "-stub"
        when {
            process {
                """
